//! Issue #479: `big` (generated by build.rs) has a frame larger than 32 KiB. A panic in
//! `may_panic` unwinds through it to `caller`'s `catch_unwind`; the unwinder must restore the
//! callee-saved registers `big` saved, where `caller` keeps its ten `k` values. Before the fix,
//! the Lean backend's save slots sat above the spill slots (beyond 32 KiB, stored through x16)
//! and `big`'s FDE had no row for x19-x28: the caller crashed after the landing pad.
use std::hint::black_box;

#[inline(never)]
fn may_panic(x: u64) {
    if black_box(x) == 7 {
        panic!("boom");
    }
}

include!(concat!(env!("OUT_DIR"), "/big.rs"));

/// Runs `big(arg)` under `catch_unwind` while ten known values are live (in callee-saved
/// registers); returns how many of them changed.
#[inline(never)]
pub fn caller(arg: u64) -> u32 {
    let k0 = black_box(0x111u64);
    let k1 = black_box(0x222u64);
    let k2 = black_box(0x333u64);
    let k3 = black_box(0x444u64);
    let k4 = black_box(0x555u64);
    let k5 = black_box(0x666u64);
    let k6 = black_box(0x777u64);
    let k7 = black_box(0x888u64);
    let k8 = black_box(0x999u64);
    let k9 = black_box(0xaaau64);
    let r = std::panic::catch_unwind(|| big(black_box(arg)));
    assert!(r.is_err() == (arg == 7));
    let mut bad = 0u32;
    for (k, want) in [
        (k0, 0x111u64),
        (k1, 0x222),
        (k2, 0x333),
        (k3, 0x444),
        (k4, 0x555),
        (k5, 0x666),
        (k6, 0x777),
        (k7, 0x888),
        (k8, 0x999),
        (k9, 0xaaa),
    ] {
        if k != want {
            bad += 1;
        }
    }
    bad
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn big_frame_returns() {
        assert_eq!(caller(3), 0);
    }

    #[test]
    fn big_frame_unwinds_and_restores_callee_saved() {
        assert_eq!(caller(7), 0);
    }
}
